from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parent / "layouts"


def b(en, zh):
    return f'<div class="bilingual"><p lang="en">{escape(en)}</p><p class="translation" lang="zh-Hant">{escape(zh)}</p></div>'


def put(n, content):
    (ROOT / f"2015-b1-page-{n:02}.html").write_text(content.rstrip() + "\n", encoding="utf-8")


put(1, (ROOT / "2014-b1-page-01.html").read_text().replace("2014", "2015"))

