def bubble(who, en, zh, outgoing=False):
    return f'<div class="chat-bubble{" outgoing" if outgoing else ""}"><strong>{escape(who)}:</strong>{b(en,zh)}</div>'


chat5 = bubble("Ajala","Hi Malcolm, I can meet Bubblegum at Atlantic Plaza at 1:30pm on the day to take photographs. Did Ms. Dong tell you where she wants the band to be photographed?","我可在下午 1:30 到 Atlantic Plaza 為 Bubblegum 拍照。Dong 女士有說在哪裏拍嗎？") + bubble("Malcolm","She said the main entrance. Don’t forget we also need you to take more photographs at 3.30pm. Don’t be late because the band are signing CDs at 4 o’clock. I’ll ask Starsky to put these points in the band’s appointments for Atlantic Plaza later and send you a copy.","在正門。另外下午 3:30 要再拍照；樂隊 4 時簽唱片，別遲到。我會請 Starsky 把這些寫入當日行程。",True)
dong = [("Dear Mr. Parker", "Parker 先生："),("Just to say again how very excited we are about Bubblegum’s visit to Atlantic Plaza.","我們非常期待 Bubblegum 到訪 Atlantic Plaza。"),("I have some important instructions for the band’s performance at 2.30pm. Could you remind the band about wearing the T-shirts we provided? Also, we’d be grateful if the band could thank Atlantic Plaza at the end of the show. After thanking Atlantic Plaza, I would then like the band to have their photograph taken with me.","下午 2:30 的表演有幾項重要指示：請樂隊穿我們提供的 T 恤，演出後感謝 Atlantic Plaza，然後與我合照。"),("As regards dining on the day, I’d like to invite the group to have breakfast with me in my office at 8.30 a.m. and then for lunch I have arranged for them to go to the ‘Fresh and Healthy’ Restaurant in Atlantic Plaza at 12.30 pm.","當天早上 8:30，我邀請樂隊到辦公室共進早餐；中午 12:30 已安排他們在商場的 Fresh and Healthy 餐廳午膳。")]
