def essay(page,key,title,zh,lead="",height=680):
    cid=f"2015-b1-{page}-{key}"
    return f'<section class="recreated-page answer-book" aria-label="2015 B1 QAB page {page-9}"><h3>{escape(title)}</h3>{lead}<p class="translation" lang="zh-Hant">{escape(zh)}</p><label class="answer-field" for="{cid}">{escape(title)}</label><textarea class="answer-box" id="{cid}" data-note="{page}-{key}" data-count-id="{cid}" style="min-height:{height}px" aria-label="{escape(title,quote=True)}"></textarea><p class="answer-count" data-count-for="{cid}">0 words</p>'


